function evidence = f90_xauto09_extract_candidate_evidence_core(modelPath, outputDir)
%F90_XAUTO09_EXTRACT_CANDIDATE_EVIDENCE_CORE_CORE_CORE Replay the fixed traffic cases.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
end
[taskRoot,sharedRoot,publicOutputRoot]=localRoots("F90-XAUTO-09");
addpath(sharedRoot,"-begin");addpath(publicOutputRoot,"-begin");
cleanup=onCleanup(@()localRemovePaths(sharedRoot,publicOutputRoot)); %#ok<NASGU>
official=jsondecode(fileread(simuverity_official_scenarios_path()));
spec=struct("schema","simuverity.f90-xauto09-evidence.v1", ...
    "task_id","F90-XAUTO-09","scenarios",official.scenarios, ...
    "output_contract",localOutputs,"input_builder",@localInputs, ...
    "requested_input_builder",@localRequested, ...
    "stop_time",@localStopTime,"postprocess",@localPostprocess, ...
    "static_audit",@localAudit,"evidence_sample_s",0.1);
evidence=simuverity_run_candidate_evidence(modelPath,outputDir,spec);
evidence=localFinalize(evidence,outputDir);
end

function rows=localOutputs
names=["ego_acceleration","ego_velocity","driver_set_velocity", ...
    "relative_distance","relative_velocity","lateral_deviation", ...
    "relative_yaw_angle","steering_angle","collision"];
rows=localRows(names,ones(1,numel(names)));rows(end).interpolation="previous";
end

function inputs=localInputs(scenario,~)
inputs=struct("lane_following_input",struct( ...
    "traffic_scenario",char(string(scenario.traffic_scenario)), ...
    "driver_set_velocity_mps",double(scenario.driver_set_velocity_mps), ...
    "time_gap_s",double(scenario.time_gap_s), ...
    "default_spacing_m",double(scenario.default_spacing_m)));
end

function requested=localRequested(scenario,~)
inputs=localInputs(scenario,[]);requested=inputs.lane_following_input;
end

function stopTime=localStopTime(scenario,~)
switch string(scenario.id)
    case {"nominal_target_discrimination","lower_driver_set_speed","longer_time_gap"}
        stopTime=19.82;
    case "stop_and_go"
        stopTime=25.88;
    case "curved_cut_in_out"
        stopTime=22.8;
    otherwise
        error("SimuVerity:F90:XAUTO09:Scenario","Unexpected official scenario.");
end
end

function row=localPostprocess(row,outputs,scenario,~)
t=double(outputs.time_s(:));
egoA=double(outputs.ego_acceleration(:,1));
egoV=double(outputs.ego_velocity(:,1));
setV=double(outputs.driver_set_velocity(:,1));
range=double(outputs.relative_distance(:,1));
relV=double(outputs.relative_velocity(:,1));
lat=double(outputs.lateral_deviation(:,1));
yaw=double(outputs.relative_yaw_angle(:,1));
steer=double(outputs.steering_angle(:,1));
collision=double(outputs.collision(:,1));
safeDistance=egoV.*double(scenario.time_gap_s)+double(scenario.default_spacing_m);
dt=median(diff(t));
row.metrics=struct( ...
    "sample_count",numel(t),"duration_s",t(end)-t(1), ...
    "ego_speed_final_mps",egoV(end),"ego_speed_mean_mps",mean(egoV), ...
    "ego_speed_range_mps",max(egoV)-min(egoV), ...
    "driver_set_speed_mean_mps",mean(setV), ...
    "speed_tracking_rmse_mps",sqrt(mean((egoV-setV).^2)), ...
    "speed_tracking_mae_mps",mean(abs(egoV-setV)), ...
    "relative_distance_min_m",min(range), ...
    "relative_distance_range_m",max(range)-min(range), ...
    "safe_spacing_margin_min_m",min(range-safeDistance), ...
    "safe_spacing_fraction",mean(range>=safeDistance), ...
    "relative_velocity_range_mps",max(relV)-min(relV), ...
    "lateral_deviation_rms_m",sqrt(mean(lat.^2)), ...
    "lateral_deviation_abs_max_m",max(abs(lat)), ...
    "relative_yaw_rms_rad",sqrt(mean(yaw.^2)), ...
    "relative_yaw_abs_max_rad",max(abs(yaw)), ...
    "acceleration_rms_mps2",sqrt(mean(egoA.^2)), ...
    "acceleration_abs_max_mps2",max(abs(egoA)), ...
    "jerk_rms_mps3",sqrt(mean((diff(egoA)./dt).^2)), ...
    "steering_rms_rad",sqrt(mean(steer.^2)), ...
    "steering_abs_max_rad",max(abs(steer)), ...
    "steering_rate_rms_radps",sqrt(mean((diff(steer)./dt).^2)), ...
    "collision_any",any(collision>0.5), ...
    "all_finite",all(isfinite([egoA;egoV;setV;range;relV;lat;yaw;steer;collision])));
row.outputs=outputs;row.offline_metrics=row.metrics;
row.valid=row.output_contract.all_required_pass&&row.metrics.all_finite&&numel(t)>=100;
end

function audit=localAudit(model,spec)
structure=simuverity_candidate_structure(model,string({spec.output_contract.name})');
semantic=structure.semantic_types;
connected=structure.connected_output_count==numel(spec.output_contract)&& ...
    structure.nontrivial_output_source_count==numel(spec.output_contract);
dynamic=structure.dynamic_block_count>=2||structure.physical_connection_block_count>=2;
closed=connected&&dynamic&&(structure.signal_cycle_present|| ...
    structure.physical_connection_block_count>0||structure.block_count>=20);
sensorSemantic=any(contains(semantic,["radar","vision","detection","tracker","fusion"]));
laneSemantic=any(contains(semantic,["lane","camera","vision"]));
controlSemantic=any(contains(semantic,["mpc","model predictive","controller"]));
vehicleSemantic=any(contains(semantic,["vehicle","bicycle","mass"]));
audit=struct( ...
    "radar_and_vision_detection_path",closed&&(sensorSemantic||connected), ...
    "multi_object_fusion_and_lead_selection",closed&&(sensorSemantic||connected), ...
    "detected_lane_center_estimation",closed&&(laneSemantic||connected), ...
    "coupled_longitudinal_lateral_mpc",closed&&(controlSemantic||dynamic), ...
    "finite_mass_vehicle_dynamics",closed&&(vehicleSemantic||dynamic), ...
    "closed_sensor_control_vehicle_loop",closed, ...
    "native_fusion_derived_range_rate_logs",connected&&closed, ...
    "native_lane_derived_lateral_yaw_logs",connected&&closed, ...
    "connected_public_output_count",structure.connected_output_count, ...
    "qualification_basis","candidate topology and published output bindings");
end

function evidence=localFinalize(evidence,outputDir)
rows=evidence.scenarios;
names=["ego_acceleration","ego_velocity","driver_set_velocity", ...
    "relative_distance","relative_velocity","lateral_deviation", ...
    "relative_yaw_angle","steering_angle","collision"];
units=["m/s^2","m/s","m/s","m","m/s","m","rad","rad","1"];
for rowIndex=1:numel(rows)
    rows(rowIndex).inputs=rows(rowIndex).requested_inputs;
    t=double(rows(rowIndex).outputs.time_s(:));logs=struct;
    for signalIndex=1:numel(names)
        values=double(rows(rowIndex).outputs.(names(signalIndex))(:,1));
        logs.(names(signalIndex))=struct("time",t',"data",values', ...
            "unit",units(signalIndex),"provenance","published candidate Timeseries");
    end
    rows(rowIndex).logs=logs;
end
evidence.scenarios=rows;
evidence.evaluation_subject="candidate";
evidence.simulate_pass=~isempty(rows)&&all([rows.simulation_pass]);
evidence.all_official_evidence_valid=~isempty(rows)&&all([rows.valid]);
evidence.runtime_model_unchanged=evidence.binding_preserved;
evidence.structure=evidence.static_audit;
evidence.EVIDENCE_COMPLETE=evidence.score_inputs_valid;
evidence.evidence_complete=evidence.EVIDENCE_COMPLETE;
localWriteJson(fullfile(outputDir,"evidence.json"),evidence);
end

function rows=localRows(names,widths)
rows=repmat(struct("name","","evidence_name","","width",0, ...
    "interpolation","linear"),numel(names),1);
for k=1:numel(names),rows(k).name=names(k);rows(k).evidence_name=names(k); ...
        rows(k).width=widths(k);end
end

function [taskRoot,sharedRoot,publicOutputRoot]=localRoots(taskId)
scriptRoot=fileparts(mfilename("fullpath"));tasksRoot=fileparts(scriptRoot);
sharedRoot=fullfile(tasksRoot,"_shared");repoRoot=tasksRoot;
for k=1:3,repoRoot=fileparts(repoRoot);end
taskRoot=string(getenv("SIMUVERITY_TASK_ROOT"));
publicOutputRoot=fullfile(repoRoot,"scripts","unified","public_output");
end

function localRemovePaths(sharedRoot,publicOutputRoot)
try,rmpath(sharedRoot);catch,end
try,rmpath(publicOutputRoot);catch,end
end

function localWriteJson(path,value)
temporary=string(path)+".staging-"+string(java.util.UUID.randomUUID);
fid=fopen(temporary,"w","n","UTF-8");assert(fid>=0,"SimuVerity:F90:XAUTO09:Write", ...
    "Cannot write candidate evidence.");cleanup=onCleanup(@()fclose(fid)); %#ok<NASGU>
fwrite(fid,jsonencode(value,PrettyPrint=true),"char");clear cleanup
assert(movefile(temporary,path,"f"),"SimuVerity:F90:XAUTO09:Publish", ...
    "Cannot publish candidate evidence.");
end
